using model::MatId;

std::size_t ix(auto value) { return static_cast<std::size_t>(value); }

FitError numeric(std::string detail) {
  return FitError{FitError::Kind::NumericIssue, std::move(detail), 0, 0.0};
}

struct Located {
  MatId mat = MatId::Lambda;
  Eigen::Index row = 0;
  Eigen::Index col = 0;
  std::size_t block = 0;
};

Located locate(MatId mat, Eigen::Index row, Eigen::Index col, std::size_t block) {
  return Located{mat, row, col, block};
}

// Standard deviations of the observed variables and units of the latent
// variables, per block; a latent unit is NaN until identified.
using driven::VariableUnits;

double unit_of(const VariableUnits& u, const Located& a) {
  const auto& s = u.observed[a.block];
  const auto& t = u.latent[a.block];
  switch (a.mat) {
    case MatId::Lambda: return s(a.row) / t(a.col);
    case MatId::Beta:   return t(a.row) / t(a.col);
    case MatId::Psi:    return t(a.row) * t(a.col);
    case MatId::Theta:  return s(a.row) * s(a.col);
    case MatId::Nu:     return s(a.row);
    case MatId::Alpha:  return t(a.row);
  }
  return 1.0;
}

// Sets the one unknown latent unit that gives `a` the unit `target`.
bool impose(VariableUnits& u, const Located& a, double target) {
  if (!std::isfinite(target) || target <= 0.0) return false;
  auto& t = u.latent[a.block];
  const auto& s = u.observed[a.block];
  auto unknown = [&t](Eigen::Index k) { return !std::isfinite(t(k)); };
  switch (a.mat) {
    case MatId::Lambda:
      if (!unknown(a.col)) return false;
      t(a.col) = s(a.row) / target;
      return true;
    case MatId::Beta:
      if (unknown(a.row) && !unknown(a.col)) { t(a.row) = target * t(a.col); return true; }
      if (unknown(a.col) && !unknown(a.row)) { t(a.col) = t(a.row) / target; return true; }
      return false;
    case MatId::Psi:
      if (a.row == a.col) {
        if (!unknown(a.row)) return false;
        t(a.row) = std::sqrt(target);
        return true;
      }
      if (unknown(a.row) && !unknown(a.col)) { t(a.row) = target / t(a.col); return true; }
      if (unknown(a.col) && !unknown(a.row)) { t(a.col) = target / t(a.row); return true; }
      return false;
    case MatId::Alpha:
      if (!unknown(a.row)) return false;
      t(a.row) = target;
      return true;
    case MatId::Theta:
    case MatId::Nu:
      return false;
  }
  return false;
}

fit_expected<VariableUnits>
compute_variable_units(const spec::LatentStructure& pt, const model::MatrixRep& rep,
               const data::SampleStats& samp) {
  if (samp.S.size() != rep.dims.size())
    return std::unexpected(numeric("coordinate units: sample and model block counts differ"));
  VariableUnits u;
  for (std::size_t b = 0; b < samp.S.size(); ++b) {
    const Eigen::MatrixXd& S = samp.S[b];
    if (S.rows() != rep.dims[b].n_observed || !S.diagonal().allFinite() ||
        (S.diagonal().array() <= 0.0).any())
      return std::unexpected(numeric(
          "coordinate units require finite positive sample variances"));
    u.observed.emplace_back(S.diagonal().array().sqrt());
    u.latent.emplace_back(Eigen::VectorXd::Constant(
        rep.dims[b].n_latent, std::numeric_limits<double>::quiet_NaN()));
  }

  struct Fixed { Located at; double value; };
  std::vector<Fixed> fixed;
  const std::size_t n_free = ix(pt.n_free());
  std::vector<std::optional<Located>> free_cell(n_free);
  for (std::size_t i = 0; i < pt.size(); ++i) {
    const model::Cell c = rep.cell_for_row[i];
    if (!c.used) continue;
    const Located at = locate(c.mat, c.row, c.col, ix(c.block));
    if (pt.free[i] > 0) {
      free_cell[ix(pt.free[i] - 1)] = at;
    } else if (std::isfinite(pt.fixed_value[i]) && pt.fixed_value[i] != 0.0) {
      fixed.push_back({at, pt.fixed_value[i]});
    }
  }
  for (const model::StructuralCell& c : rep.structural_cells) {
    if (std::isfinite(c.value) && c.value != 0.0)
      fixed.push_back({locate(c.mat, c.row, c.col, ix(c.block)), c.value});
  }

  // Markers, then fixed variances.
  for (const Fixed& f : fixed)
    if (f.at.mat == MatId::Lambda) impose(u, f.at, std::abs(f.value));
  for (const Fixed& f : fixed)
    if (f.at.mat == MatId::Psi && f.at.row == f.at.col && f.value > 0.0)
      impose(u, f.at, f.value);

  std::map<std::int32_t, std::vector<std::size_t>> by_group;
  if (pt.eq_groups.size() == n_free)
    for (std::size_t k = 0; k < n_free; ++k)
      if (free_cell[k]) by_group[pt.eq_groups[k]].push_back(k);

  bool changed = true;
  while (changed) {
    changed = false;
    for (const Fixed& f : fixed)
      if (f.at.mat == MatId::Beta)
        changed = impose(u, f.at, std::abs(f.value)) || changed;
    for (const auto& entry : by_group) {
      const std::vector<std::size_t>& members = entry.second;
      if (members.size() < 2) continue;
      double target = std::numeric_limits<double>::quiet_NaN();
      for (std::size_t k : members) {
        const double v = unit_of(u, *free_cell[k]);
        if (std::isfinite(v) && v > 0.0) { target = v; break; }
      }
      if (!std::isfinite(target)) continue;
      for (std::size_t k : members)
        if (!std::isfinite(unit_of(u, *free_cell[k])))
          changed = impose(u, *free_cell[k], target) || changed;
    }
    if (changed) continue;
    // Effect coding and other free charts: the indicators' mean unit.
    std::vector<Eigen::VectorXd> sum, count;
    for (const auto& t : u.latent) {
      sum.emplace_back(Eigen::VectorXd::Zero(t.size()));
      count.emplace_back(Eigen::VectorXd::Zero(t.size()));
    }
    for (const auto& cell : free_cell) {
      if (!cell) continue;
      const Located& a = *cell;
      // Only loadings and latent regressions have a latent column.
      if (a.mat != MatId::Lambda && a.mat != MatId::Beta) continue;
      const auto& t = u.latent[a.block];
      if (std::isfinite(t(a.col))) continue;
      if (a.mat == MatId::Lambda) {
        sum[a.block](a.col) += u.observed[a.block](a.row);
        count[a.block](a.col) += 1.0;
      } else if (a.mat == MatId::Beta && std::isfinite(t(a.row))) {
        sum[a.block](a.col) += t(a.row);
        count[a.block](a.col) += 1.0;
      }
    }
    for (std::size_t b = 0; b < u.latent.size(); ++b)
      for (Eigen::Index k = 0; k < u.latent[b].size(); ++k)
        if (count[b](k) > 0.0 && !std::isfinite(u.latent[b](k))) {
          u.latent[b](k) = sum[b](k) / count[b](k);
          changed = true;
        }
  }
  for (std::size_t b = 0; b < u.latent.size(); ++b) {
    const double fallback = u.observed[b].size() > 0 ? u.observed[b].mean() : 1.0;
    for (Eigen::Index k = 0; k < u.latent[b].size(); ++k)
      if (!std::isfinite(u.latent[b](k))) u.latent[b](k) = fallback;
  }
  return u;
}

